UPDATE municipios SET why_json = json_insert(COALESCE(why_json, '[]'), '$[#]', '🏖️ Playas: Punto de referencia para acceder a la isla de Tabarca') WHERE codigo_ine = '03035' AND COALESCE(why_json, '[]') NOT LIKE '%Punto de referencia %';
UPDATE municipios SET why_json = json_insert(COALESCE(why_json, '[]'), '$[#]', '🌿 Naturaleza: Punto de referencia para acceder a la isla de Tabarca') WHERE codigo_ine = '03035' AND COALESCE(why_json, '[]') NOT LIKE '%Punto de referencia %';
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, fuente) VALUES ('03035', 'accidente geográfico', 'Cabo de Santa Pola', 'articulo_web');

